"use client";

import { useState } from "react";
import {
    BarChart3,
    TrendingUp,
    TrendingDown,
    DollarSign,
    Package,
    Calendar,
    Download,
    FileText,
    Loader2
} from "lucide-react";
import { useData } from "@/lib/hooks";
import { generateReportPDF } from "@/lib/pdf";

export default function ReportsPage() {
    const [selectedPeriod, setSelectedPeriod] = useState("This Month");
    const { data: reportData, loading } = useData<any>("/api/reports");

    if (loading) return <div className="flex justify-center py-12"><Loader2 className="h-10 w-10 text-purple-600 animate-spin" /></div>;

    const monthlySales = reportData?.monthlySales || [];
    const topProducts = reportData?.topProducts || [];

    const totalSales = monthlySales.reduce((sum: number, m: any) => sum + m.sales, 0);
    const totalPurchases = monthlySales.reduce((sum: number, m: any) => sum + m.purchases, 0);
    const netProfit = totalSales - totalPurchases;

    const exportStats = () => {
        generateReportPDF({
            "Total Sales": `PKR ${totalSales.toLocaleString()}`,
            "Total Purchases": `PKR ${totalPurchases.toLocaleString()}`,
            "Net Profit": `PKR ${netProfit.toLocaleString()}`,
            "Report Period": selectedPeriod,
            "Top Selling Product": topProducts[0]?.name || "N/A"
        }, "Hospital Performance Report");
    };

    return (
        <div className="flex flex-col gap-8 animate-fade-in-up">
            {/* Page Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900">Hospital Analytics</h1>
                    <p className="text-gray-500 mt-1">Real-time financial performance and product insights.</p>
                </div>
                <div className="flex items-center gap-3">
                    <select
                        value={selectedPeriod}
                        onChange={(e) => setSelectedPeriod(e.target.value)}
                        className="h-11 rounded-xl border border-gray-200 px-4 text-sm bg-white focus:ring-2 focus:ring-purple-500/20"
                    >
                        <option>This Week</option>
                        <option>This Month</option>
                        <option>This Year</option>
                    </select>
                    <button
                        onClick={exportStats}
                        className="btn-primary flex items-center gap-2"
                    >
                        <Download className="h-4 w-4" />
                        Export Data
                    </button>
                </div>
            </div>

            {/* Aggregated Stats Cards */}
            <div className="grid gap-6 md:grid-cols-3">
                <div className="card-premium rounded-2xl p-6 bg-gradient-to-br from-green-50 to-white border-green-100">
                    <div className="flex justify-between items-start mb-4">
                        <div className="w-12 h-12 rounded-xl bg-green-500 flex items-center justify-center text-white shadow-lg shadow-green-500/20">
                            <TrendingUp className="h-6 w-6" />
                        </div>
                        <span className="badge badge-success">Live Stats</span>
                    </div>
                    <p className="text-sm text-gray-500 font-bold uppercase tracking-wider">Total Revenue</p>
                    <p className="text-3xl font-black text-gray-900 mt-1">PKR {totalSales.toLocaleString()}</p>
                </div>

                <div className="card-premium rounded-2xl p-6 bg-gradient-to-br from-orange-50 to-white border-orange-100">
                    <div className="flex justify-between items-start mb-4">
                        <div className="w-12 h-12 rounded-xl bg-orange-500 flex items-center justify-center text-white shadow-lg shadow-orange-500/20">
                            <Package className="h-6 w-6" />
                        </div>
                        <span className="badge badge-warning">Shipments</span>
                    </div>
                    <p className="text-sm text-gray-500 font-bold uppercase tracking-wider">Inventory Cost</p>
                    <p className="text-3xl font-black text-gray-900 mt-1">PKR {totalPurchases.toLocaleString()}</p>
                </div>

                <div className="card-premium rounded-2xl p-6 bg-gradient-to-br from-purple-50 to-white border-purple-100">
                    <div className="flex justify-between items-start mb-4">
                        <div className="w-12 h-12 rounded-xl bg-purple-500 flex items-center justify-center text-white shadow-lg shadow-purple-500/20">
                            <DollarSign className="h-6 w-6" />
                        </div>
                        <span className="badge badge-info">Net Gain</span>
                    </div>
                    <p className="text-sm text-gray-500 font-bold uppercase tracking-wider">Net Profit</p>
                    <p className="text-3xl font-black text-purple-600 mt-1">PKR {netProfit.toLocaleString()}</p>
                </div>
            </div>

            <div className="grid gap-8 lg:grid-cols-2">
                {/* Revenue Growth Chart */}
                <div className="card-premium rounded-3xl p-8">
                    <div className="flex items-center justify-between mb-8">
                        <div>
                            <h3 className="text-xl font-bold text-gray-900">Revenue Growth</h3>
                            <p className="text-sm text-gray-500">Sales vs Purchases Analysis</p>
                        </div>
                        <BarChart3 className="h-6 w-6 text-gray-400" />
                    </div>

                    <div className="space-y-8">
                        {monthlySales.map((month: any, i: number) => (
                            <div key={i}>
                                <div className="flex justify-between items-end mb-3">
                                    <span className="font-bold text-gray-700 text-sm italic">{month.month} 2024</span>
                                    <div className="flex gap-4">
                                        <div className="text-right">
                                            <p className="text-[10px] text-green-600 font-bold uppercase">Sales</p>
                                            <p className="font-bold text-gray-900">PKR {month.sales.toLocaleString()}</p>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-[10px] text-orange-600 font-bold uppercase">Cost</p>
                                            <p className="font-bold text-gray-900">PKR {month.purchases.toLocaleString()}</p>
                                        </div>
                                    </div>
                                </div>
                                <div className="h-3 w-full bg-gray-100 rounded-full overflow-hidden flex">
                                    <div
                                        className="h-full bg-green-500 transition-all duration-1000 ease-out"
                                        style={{ width: `${(month.sales / (month.sales + month.purchases)) * 100}%` }}
                                    />
                                    <div
                                        className="h-full bg-orange-400 transition-all duration-1000 ease-out"
                                        style={{ width: `${(month.purchases / (month.sales + month.purchases)) * 100}%` }}
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Performance Table */}
                <div className="card-premium rounded-3xl p-8 overflow-hidden">
                    <h3 className="text-xl font-bold text-gray-900 mb-6">Top Selling Medicines</h3>
                    <div className="space-y-4">
                        {topProducts.map((p: any, i: number) => (
                            <div key={i} className="flex items-center gap-4 p-4 rounded-2xl bg-gray-50 hover:bg-purple-50 transition-colors group">
                                <span className="text-2xl font-black text-gray-200 group-hover:text-purple-200 transition-colors">#{i + 1}</span>
                                <div className="flex-1">
                                    <p className="font-bold text-gray-900 group-hover:text-purple-600 transition-colors">{p.name}</p>
                                    <p className="text-xs text-gray-500 font-medium">{p.sold} Units Moved</p>
                                </div>
                                <div className="text-right">
                                    <p className="font-bold text-green-600">PKR {p.revenue.toLocaleString()}</p>
                                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tighter">Gross Rev</p>
                                </div>
                            </div>
                        ))}
                    </div>
                    <button className="w-full mt-6 py-4 rounded-2xl border-2 border-dashed border-gray-200 text-gray-400 font-bold text-sm hover:border-purple-300 hover:text-purple-500 transition-all">
                        View Extensive Sales Audit
                    </button>
                </div>
            </div>
        </div>
    );
}
